from collections import deque

def shortestDistance(N, M, A, X, Y):
    if A[0][0] == 0:
        return -1

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(0, 0, 0)])  # (x, y, steps)
